/// <summary>
/// MPJ_34596_TransferOrderFinalisation ,Service class for transfer Shiping list generation service
/// </summary>
class MetTransferOrderShipmentWorkbenchRouteUpdateService extends SysOperationServiceBase
{
    #OCCRetryCount

   
    MetTransferOrderShipmentWorkbenchRouteUpdateContract    dataContract;
    BatchHeader                                          batchHeader;
    InventTransferId                                     transferId;
    InventTransferTable                           inventTransferTable;
    METInventTransferTableExt                   metInventTransferTableExt;

   
}

Method.Source:
/// <summary>
/// processing logic
/// </summary>
/// <param name = "_dataContract">The data contract</param>
public void process(MetTransferOrderShipmentWorkbenchRouteUpdateContract _dataContract)
{
    dataContract = _dataContract;
     
    int recordCount;
    try
    {
        ttsbegin;
        for(recordCount = 1; recordCount <= conLen(dataContract.parmTransferOrderList()); recordCount++)
        {
            transferId    = conPeek(dataContract.parmTransferOrderList(),recordCount);
            select  firstonly inventTransferTable where inventTransferTable.TransferId == transferId
                 join forupdate metInventTransferTableExt where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId;
            if(metInventTransferTableExt.RecId)
            {
                metInventTransferTableExt.Route     = dataContract.parmPrimaryRouteChange();
                metInventTransferTableExt.RouteStop = dataContract.parmRouteStopChange();
                metInventTransferTableExt.update();
            }
           
       
        }
        ttscommit;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() != 0)
        {
            throw Exception::UpdateConflict;
        }
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::UpdateConflictNotRecovered;
        }
        retry;
    }
  
}
